      if(['S15-CAN-MERCHANT','S15-CAN-SCAFFOLD','S15-CAN-STRIP','S15-CAN-CALENDAR'].includes(t.template_code)) throw new Error('S15_REVIEW: confirmation outstanding '+t.id);
