function _s15ApplyPlan(store,journal,plan) {
  store.update('CommitJournal',journal.id,{state:'Applying'});
  try {
    for(let i=0;i<plan.ops.length;i++) {
      const op=plan.ops[i],current=store.get(op.table,op.id), intended=op.insert||Object.assign({},op.before,op.patch);
      const keys=op.insert?Object.keys(op.insert):Object.keys(op.patch);
      const equal=(a,b,ks)=>ks.every(k=>{const av=a&&a[k],bv=b&&b[k];if(Object.prototype.toString.call(av)==='[object Date]'||Object.prototype.toString.call(bv)==='[object Date]'){if((typeof av==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(av))||(typeof bv==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(bv)))return _s15Date(av)===_s15Date(bv);return new Date(av).getTime()===new Date(bv).getTime();}return JSON.stringify(av===undefined?null:av)===JSON.stringify(bv===undefined?null:bv);});
      if(!current&&op.insert) store.insert(op.table,op.insert);
      else if(current&&equal(current,intended,keys)) { /* prior partial application verified */ }
      else if(current&&op.before&&equal(current,op.before,Object.keys(op.before))) store.update(op.table,op.id,op.patch);
      else throw new Error('S15_RECOVERY_REQUIRED: changed entity '+op.table+'/'+op.id);
      const aid='AE-'+plan.commit+'-'+i;
      if(!store.get('AuditEvents',aid)) store.insert('AuditEvents',{id:aid,entity_type:op.table,entity_id:op.id,action:'S15'+plan.kind,before_json:op.before?JSON.stringify(op.before):null,after_json:JSON.stringify(intended),initiating_actor:plan.input.actor,executing_service:'S15 DEV',timestamp:plan.now,correlation_id:plan.input.command_id,reason:plan.input.reason,commit_id:plan.commit,created_at:plan.now});
    }
    store.update('CommitJournal',journal.id,{state:'Committed',committed_at:plan.now});
  } catch(e) {store.update('CommitJournal',journal.id,{state:'RecoveryRequired'});throw e;}
  return {ok:true,status:store.get('Jobs',plan.input.job_id).workflow_stage,review:plan.risks.length>0,affected:plan.ops.length,external_calls:0};
}
function _s15Execute(kind,input,store) {
  // Store.withLock is required: cloud uses ScriptLock, local tests provide a lock model.
  if(!store.withLock) throw new Error('S15_REFUSED: lock adapter required');
  return store.withLock(function(){
    const scope=_s15Scope(store,input), id='CJ-S15-'+input.command_id, existing=store.get('CommitJournal',id);
    if(existing) {
      const plan=JSON.parse(existing.changes_json);
      if(plan.kind!==kind||JSON.stringify(plan.input)!==JSON.stringify(_s15Copy(input))) throw new Error('S15_REVIEW: conflicting command replay');
      if(existing.state==='Committed') return {ok:true,replay:true,status:scope.job.workflow_stage,external_calls:0};
      return _s15ApplyPlan(store,existing,plan);
    }
    if(store.list('CommitJournal').some(j=>j.entity_id===input.job_id&&j.state!=='Committed')) throw new Error('S15_RECOVERY_REQUIRED: pending job journal');
    if(input.expected_version!==Number(scope.job.version)) throw new Error('S15_REVIEW: stale job revision');
    const plan=_s15Plan(input,store,kind), journal={id,commit_id:plan.commit,state:'Prepared',command_id:input.command_id,entity_type:'Jobs',entity_id:input.job_id,expected_version:input.expected_version,changes_json:JSON.stringify(plan),prepared_at:plan.now,committed_at:null,created_at:plan.now};
    store.insert('CommitJournal',journal);
    return _s15ApplyPlan(store,journal,plan);
  });
}
function _s15SetModes(store,enable) {
  _s15GuardStore(store);
  return store.withLock(function(){
    const rows=S15_ENABLED.map(id=>{
      const a=store.list('ReleaseModes').filter(r=>r.function_id===id),d=S15_FUNCTIONS[id];
      if(a.length!==1||a[0].target_release!==d[0]||!((a[0].mode==='Disabled'&&a[0].authorised_job_scope==='None')||(a[0].mode===d[1]&&a[0].authorised_job_scope==='Pilot'))) throw new Error('S15_REFUSED: unexpected starting mode '+id);
      return a[0];
    });
    for(const r of rows) {
      const mode=enable?S15_FUNCTIONS[r.function_id][1]:'Disabled',scope=enable?'Pilot':'None';
      if(r.mode!==mode||r.authorised_job_scope!==scope) store.update('ReleaseModes',r.id,{mode,authorised_job_scope:scope,updated_at:new Date().toISOString(),updated_by:'S15-modes',version:Number(r.version||0)+1});
    }
    return {ok:true,enabled:enable,functions:S15_ENABLED};
  });
}

/* Minimal synthetic fixture; source-specific template codes, not invented spec IDs. */
const S15_TITLES={
 'S15-CAN-CUSTOMER':'Notify customer using reviewed cancellation message',
 'S15-CAN-INSTALLER':'Notify installer and cancel future commitment',
 'S15-CAN-MERCHANT':'Merchant confirmed latest cancellation and goods disposition',
 'S15-CAN-SCAFFOLD':'Scaffolder acknowledged cancellation',
 'S15-CAN-STRIP':'Arrange safe strip and confirm actual removal',
 'S15-CAN-CALENDAR':'Reconcile Calendar removal using retained event ID',
 'S15-CAN-STOCK':'Review goods: receive, hold, return or reallocate; retain actual cost',
 'S15-CAN-XERO':'Review/cancel Xero invoice',
 'S15-CAN-FINANCE':'Review finance obligations and existing payment route',
 'S15-CAN-SIGNABLE':'Cancel/amend Signable contract with evidence',
 'S15-CAN-PHOENIX':'Review Phoenix agreement and evidence obligations',
 'S15-CAN-GHL':'Record human GHL cancellation stage action',
 'S15-CAN-SALES':'Notify salesperson of cancellation',
 'S15-CAN-LEGACY':'Close retained paper, Trello and whiteboard records',
 'S15-CAN-REVIEW':'Review partial work, retained evidence and unresolved obligations',
 'S15-REOPEN-REVIEW':'Review fresh planning and invoice/order reuse before booking'
};
function _s15FixtureRows(){
 const n='2026-11-01T12:00:00.000Z', base={created_at:n,created_by:'S15',updated_at:n,updated_by:'S15',version:1,source_system:'S15-fixture',commit_id:'S15-fixture'};
 return {
  Jobs:[Object.assign({},base,{id:'J-s15-clean',job_id:'SS-S15C-LEAN',display_name:'S15 Synthetic',customer_id:'CUST-s15',workflow_stage:'Booked',finance_route:'Standard',contract_status:'NotSent',pilot_job:true,release_scope:'R1',roof_required:true,electrical_required:false,scaffold_required:false,handover_status:'NotReady',financial_status:'Pending'})],
  WorkPackages:[Object.assign({},base,{id:'WP-s15-roof',job_id:'J-s15-clean',trade:'Roof',required:true,status:'Scheduled',planned_start:'2026-11-16',planned_end:'2026-11-16',revision:1,sequence:1,commissioning_required:true})],
  Allocations:[Object.assign({},base,{id:'ALLOC-s15-roof',work_package_id:'WP-s15-roof',person_id:'PERSON-s15-installer',role:'Lead',active:true,start_at:'2026-11-16',end_at:'2026-11-16'})],
  Tasks:[Object.assign({},base,{id:'TASK-s15-booking',job_id:'J-s15-clean',template_code:'BKG04',instance_key:'S15-booking',group:'Booking',title:'Send synthetic booking notice',owner_id:'PERSON-s15-office',related_entity_type:'Jobs',related_entity_id:'J-s15-clean',status:'Open'})],
  People:[Object.assign({},base,{id:'PERSON-s15-office',email:'s15-office@dev.example.invalid',display_name:'S15 Synthetic Office',role:'Office',active:true}),Object.assign({},base,{id:'PERSON-s15-installer',email:'s15-installer@dev.example.invalid',display_name:'S15 Synthetic Installer',role:'Installer',active:true})],
  TaskTemplates:Object.keys(S15_TITLES).map(code=>Object.assign({},base,{source_system:undefined,id:'TPL-'+code,template_code:code,title:S15_TITLES[code],group:'Cancellation',default_owner_role:'Office',trigger_event:code==='S15-REOPEN-REVIEW'?'S15 reinstatement':'S15 cancellation',due_rule:'Cancellation review now',evidence_required:'Reviewed outcome reference; confirmations must match latest entity revision',active:true,template_version:'S15-1.0'}))
 };
}
function _s15Seed(store){
 const rows=_s15FixtureRows();
 for(const r of rows.TaskTemplates)delete r.source_system;
 // Preflight all collisions before writing; partial fixture writes can be retried.
 for(const table of Object.keys(rows)) for(const row of rows[table]) {const old=store.get(table,row.id);if(old&&old.created_by!=='S15')throw new Error('S15_REFUSED: fixture ID collision '+row.id);}
 for(const table of Object.keys(rows)) for(const row of rows[table]) if(!store.get(table,row.id))store.insert(table,row);
}
function _s15CancelInput(){return{command_id:'S15-CLOUD-CANCEL',job_id:'J-s15-clean',actor:'PERSON-s15-office',reason:'Synthetic pre-install cancellation',expected_version:1,effective_date:'2026-11-02',work_performed:'None',material_state:'None',scaffold_state:'None',finance_review:'Synthetic fixture has no invoices or payments',legacy_state:'None'};}
function _s15Smoke(store,execute){
 const input=_s15CancelInput();execute('Cancel',input,store);execute('Cancel',input,store);
 const pending=store.list('Tasks').filter(t=>t.job_id===input.job_id&&t.group==='Cancellation'&&t.template_code!=='S15-REOPEN-REVIEW');
 const close={command_id:'S15-CLOUD-CLOSE',job_id:input.job_id,actor:input.actor,reason:'Synthetic obligations explicitly tracked; no external completion claimed',expected_version:2,tracked_obligations:pending.map(t=>({task_id:t.id,reference:'S15-SYNTHETIC-TRACKING',reason:'Retained owned test obligation; no actual customer or external commitment'}))};
 execute('Close',close,store);
 const reopen={command_id:'S15-CLOUD-REOPEN',job_id:input.job_id,actor:input.actor,reason:'Synthetic controlled reopen',expected_version:3,new_date:'2026-11-23',commitment_review:'No orders/events in clean synthetic fixture; fresh unallocated package only',finance_review:'No synthetic invoices/payments; existing route remains review-only',evidence_reference:'S15-SYNTHETIC-REVIEW'};
 execute('Reinstate',reopen,store);execute('Reinstate',reopen,store);
 const j=store.get('Jobs',input.job_id),wp=store.list('WorkPackages').filter(w=>w.job_id===j.id),journals=store.list('CommitJournal').filter(c=>c.entity_id===j.id);
 const pass=j.workflow_stage==='Prebooking'&&j.version===4&&wp.length===2&&store.get('WorkPackages','WP-s15-roof').status==='Cancelled'&&store.get('Allocations','ALLOC-s15-roof').active===false&&store.get('Tasks','TASK-s15-booking').status==='Cancelled'&&journals.length===3&&journals.every(c=>c.state==='Committed')&&store.list('AuditEvents').some(a=>a.action==='S15Cancel'&&a.entity_id===j.id)&&store.list('InvoiceStages').filter(s=>s.job_id===j.id).length===0;
 return {pass,detail:{job_stage:j.workflow_stage,job_version:j.version,packages:wp.length,journals:journals.length,external_calls:0}};
}

/* Header-checked enumeration adapter; shared ScriptLock for every S15 mutation. */
function _s15CloudGuard(){
 const ss=SpreadsheetApp.getActiveSpreadsheet(),c=JSON.parse(PropertiesService.getScriptProperties().getProperty('S01_CONFIG')||'null');
 if(ss.getId()!==S15_DEV_SHEET_ID||!c||c.environment!=='DEV')throw new Error('S15_REFUSED: exact DEV sheet/environment required');
 return ss;
}
function _s15Sheet(ss,name){
 const matches=ss.getSheets().filter(s=>s.getName()===name);
 if(matches.length!==1)throw new Error('S15_SCHEMA: missing/duplicate tab '+name);
 const sh=matches[0],headers=S15_HEADERS[name];
 if(!headers||sh.getLastColumn()!==headers.length||JSON.stringify(sh.getRange(1,1,1,headers.length).getValues()[0])!==JSON.stringify(headers))throw new Error('S15_SCHEMA: header mismatch '+name);
 return sh;
}
function _s15Cell(value){return value===null||value===undefined?'':typeof value==='string'&&/^[=+@'\-]/.test(value)?"'"+value:value;}
function _s15CloudStore(){
 const ss=_s15CloudGuard();
 function list(name){const sh=_s15Sheet(ss,name),h=S15_HEADERS[name];if(sh.getLastRow()<2)return[];return sh.getRange(2,1,sh.getLastRow()-1,h.length).getValues().map(row=>{const x={};h.forEach((k,i)=>x[k]=row[i]===''?null:row[i]);return x;}).filter(r=>r.id);}
 return {
  getSheetId:function(){return ss.getId();},getEnvironment:function(){_s15CloudGuard();return'DEV';},list,
  get:function(name,id){const rows=list(name).filter(r=>r.id===id);if(rows.length>1)throw new Error('S15_SCHEMA: duplicate ID '+id);return rows[0]||null;},
  insert:function(name,row){const sh=_s15Sheet(ss,name),h=S15_HEADERS[name];if(list(name).some(r=>r.id===row.id))throw new Error('S15_SCHEMA: duplicate insert '+row.id);if(sh.getLastRow()>=sh.getMaxRows())throw new Error('S15_CAPACITY: '+name);for(const k of Object.keys(row))if(!h.includes(k))throw new Error('S15_SCHEMA: unknown field '+name+'.'+k);sh.getRange(sh.getLastRow()+1,1,1,h.length).setValues([h.map(k=>_s15Cell(row[k]))]);SpreadsheetApp.flush();},
  update:function(name,id,patch){const sh=_s15Sheet(ss,name),h=S15_HEADERS[name],values=sh.getRange(2,1,Math.max(1,sh.getLastRow()-1),h.length).getValues(),indices=[];values.forEach((r,i)=>{if(r[0]===id)indices.push(i);});if(indices.length!==1)throw new Error('S15_SCHEMA: update row '+id);const idx=indices[0],row=values[idx];for(const k of Object.keys(patch)){if(!h.includes(k))throw new Error('S15_SCHEMA: unknown field '+name+'.'+k);row[h.indexOf(k)]=patch[k];}sh.getRange(idx+2,1,1,h.length).setValues([row.map(_s15Cell)]);SpreadsheetApp.flush();},
  withLock:function(fn){const lock=LockService.getScriptLock();if(!lock.tryLock(5000))throw new Error('S15_BUSY');try{return fn();}finally{lock.releaseLock();}}
 };
}
function _s15Result(name,fn){try{const result=fn(),r={test:name,pass:result.pass===undefined?result.ok!==false:result.pass,detail:result.detail||result};console.log(JSON.stringify(r));return r;}catch(e){const r={test:name,pass:false,detail:String(e.message||e)};console.log(JSON.stringify(r));return r;}}
function restoreS15SafeState(){return _s15Result('S15 restore',function(){return _s15SetModes(_s15CloudStore(),false);});}
function runS15FixtureDryRun(){return _s15Result('S15 dry run',function(){const s=_s15CloudStore();for(const n of Object.keys(S15_HEADERS))s.list(n);_s15ModesSnapshot(s);return{ok:true,existing_job:!!s.get('Jobs','J-s15-clean')};});}
function runS15FixtureApply(){return _s15Result('S15 fixture apply',function(){const s=_s15CloudStore();return s.withLock(function(){_s15Seed(s);return{ok:true};});});}
function runS15FixtureValidate(){return _s15Result('S15 fixture validate',function(){const s=_s15CloudStore(),rows=_s15FixtureRows();for(const t of Object.keys(rows))for(const r of rows[t]){const row=s.get(t,r.id);if(!row||row.created_by!=='S15')throw new Error('S15_FIXTURE: '+r.id);}return{ok:true};});}
function runS15EnableFunctionsForSyntheticTest(){return _s15Result('S15 enable',function(){return _s15SetModes(_s15CloudStore(),true);});}
function runS15HappyPathTest(){return _s15Result('S15 happy path',function(){return _s15Smoke(_s15CloudStore(),_s15Execute);});}
